package srv.scrt.vwr.util.logs


/**
 * Custom Timber Debug Tree that adds the file name, line number, and method name
 * This is a class imported from another project which was generated by chatGPT.
 * No Copyright is claimed for this class, and it is free to use.
 * */

import timber.log.Timber

class CustomDebugTree : Timber.DebugTree() {

    override fun log(priority: Int, tag: String?, message: String, t: Throwable?) {
        val stackTrace = Throwable().stackTrace

        // Find the first stack trace element that is NOT Timber and NOT this class
        val element = stackTrace.firstOrNull {
            it.className !in listOf(
                Timber::class.java.name,
                CustomDebugTree::class.java.name,
                "timber.log.Timber\$Forest",
                "timber.log.Timber\$Tree"
            )
        }

        val prefix = if (element != null) {
            "[(${element.fileName}:${element.lineNumber})->${element.methodName}]"
        } else {
            "[Unknown Source]"
        }

        super.log(priority, tag, "$prefix $message", t)
    }
}
